+public class LicenseHeadersPrecommitPlugin extends PrecommitPlugin implements InternalPlugin {
+    @Inject
+    public LicenseHeadersPrecommitPlugin(ProviderFactory providerFactory) {
+        this.providerFactory = providerFactory;
