+            }
+        }
+        standardReport.endReport();
+        writer.flush();
+        writer.close();
+        return stats;
+    }
+
+    private static List<String> unapprovedFiles(File xmlReportFile) {
+        try {
+            NodeList resourcesNodes = DocumentBuilderFactory.newInstance()
+                .newDocumentBuilder()
+                .parse(xmlReportFile)
+                .getElementsByTagName("resource");
