+        Runnable decoratedCommand = decorateRunnable(command);
+        Scheduler.ScheduledCancellable schedule = threadPool.schedule(decoratedCommand, new TimeValue(delay, unit), executorName);
+        return new ReactorFuture<>(schedule);
+    }
