+                    } else {
+                        assertThat(realBreaker.getUsed(), equalTo(preallocatedBytes));
+                    }
+                    if (current > 0 && randomBoolean()) {
+                        long delta = randomLongBetween(Math.max(-current, -realBreaker.getLimit() / 100), 0);
